-- Authorized historical import. No invoice posting, repricing or job closure.
CREATE TABLE project_source_imports(id text PRIMARY KEY,filename text NOT NULL,sha256 text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_project_source BEFORE UPDATE OR DELETE ON project_source_imports FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TABLE project_source_links(job_key text PRIMARY KEY,site_id integer NOT NULL REFERENCES sites(id),import_id text NOT NULL REFERENCES project_source_imports(id),snapshot jsonb NOT NULL);
CREATE TRIGGER immutable_project_source_link BEFORE UPDATE OR DELETE ON project_source_links FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TABLE project_checkpoint_versions(id uuid PRIMARY KEY,job_key text NOT NULL,department text NOT NULL CHECK(department IN ('Operations','Accounts')),version integer NOT NULL CHECK(version>0),snapshot jsonb NOT NULL,request_key uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_key,department,version));
CREATE TRIGGER immutable_project_checkpoint BEFORE UPDATE OR DELETE ON project_checkpoint_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TABLE archived_sample_closures(closure_id uuid PRIMARY KEY REFERENCES accounts_job_closures(id),reason text NOT NULL,archived_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_sample_archive BEFORE UPDATE OR DELETE ON archived_sample_closures FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE VIEW accounts_active_job_closures AS SELECT j.* FROM accounts_job_closures j WHERE NOT EXISTS(SELECT 1 FROM archived_sample_closures a WHERE a.closure_id=j.id);
