 IF (SELECT count(*) FROM ubl_site_orders WHERE legacy_ipo_number::integer IN (285,286,297,287,288,289,290,291,294,296,298,299,300,301,307,308,310,312,313,232,314,311,306,293,292,295,302,304,303,316,317,320,309,319,318,332)) <> 36 THEN RAISE EXCEPTION 'UBL source match is incomplete'; END IF;
