INSERT INTO project_source_links(job_key,site_id,import_id,snapshot)
SELECT 'ubl:'||o.site_id,o.site_id,'ubl-progress-2026-10-11',x FROM project_source_imports i CROSS JOIN LATERAL jsonb_array_elements(i.snapshot->'linked') x JOIN ubl_site_orders o ON o.legacy_ipo_number=(x->>'ipo') WHERE i.id='ubl-progress-2026-10-11';
INSERT INTO archived_sample_closures SELECT j.id,'Management requested removal of CHP-320 sample workflow; original records retained.' FROM accounts_job_closures j JOIN ubl_site_orders o ON j.job_key='ubl:'||o.site_id WHERE o.legacy_ipo_number='320';
UPDATE inventory_reports r SET job_key='archived-sample:'||r.job_key||':'||r.id WHERE r.job_key=(SELECT 'ubl:'||site_id FROM ubl_site_orders WHERE legacy_ipo_number='320');
